    pub(crate) fn compare_diagnostic_common_props(
        &self,
        other: &Document,
        a: &DiagnosticCommonProps,
        b: &DiagnosticCommonProps,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_authentication_timeout() != b.get_authentication_timeout() {
            return Err(format!("{path}: AUTHENTICATION_TIMEOUT mismatch"));
        }
        let list_a = a.get_debounce_algorithm_props();
        let list_b = b.get_debounce_algorithm_props();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DEBOUNCE_ALGORITHM_PROPS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .diagnostic_debounce_algorithm_props
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.DEBOUNCE_ALGORITHM_PROPS[{index}]: id not found in own arena")
                })?;
            let y = other
                .diagnostic_debounce_algorithm_props
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.DEBOUNCE_ALGORITHM_PROPS[{index}]: id not found in other arena")
                })?;
            self.compare_diagnostic_debounce_algorithm_props(
                other,
                x,
                y,
                &format!("{path}.DEBOUNCE_ALGORITHM_PROPS[{index}]"),
            )?;
        }
        if a.get_default_endianness() != b.get_default_endianness() {
            return Err(format!("{path}: DEFAULT_ENDIANNESS mismatch"));
        }
        if a.get_event_combination_reporting_behavior()
            != b.get_event_combination_reporting_behavior()
        {
            return Err(format!(
                "{path}: EVENT_COMBINATION_REPORTING_BEHAVIOR mismatch"
            ));
        }
        if a.get_max_number_of_request_correctly_received_response_pending()
            != b.get_max_number_of_request_correctly_received_response_pending()
        {
            return Err(format!(
                "{path}: MAX_NUMBER_OF_REQUEST_CORRECTLY_RECEIVED_RESPONSE_PENDING mismatch"
            ));
        }
        if a.get_occurrence_counter_processing() != b.get_occurrence_counter_processing() {
            return Err(format!("{path}: OCCURRENCE_COUNTER_PROCESSING mismatch"));
        }
        if a.get_reset_confirmed_bit_on_overflow() != b.get_reset_confirmed_bit_on_overflow() {
            return Err(format!("{path}: RESET_CONFIRMED_BIT_ON_OVERFLOW mismatch"));
        }
        if a.get_reset_pending_bit_on_overflow() != b.get_reset_pending_bit_on_overflow() {
            return Err(format!("{path}: RESET_PENDING_BIT_ON_OVERFLOW mismatch"));
        }
        if a.get_response_on_all_request_sids() != b.get_response_on_all_request_sids() {
            return Err(format!("{path}: RESPONSE_ON_ALL_REQUEST_SIDS mismatch"));
        }
        if a.get_response_on_second_declined_request()
            != b.get_response_on_second_declined_request()
        {
            return Err(format!(
                "{path}: RESPONSE_ON_SECOND_DECLINED_REQUEST mismatch"
            ));
        }
        if a.get_type_of_event_combination_supported()
            != b.get_type_of_event_combination_supported()
        {
            return Err(format!(
                "{path}: TYPE_OF_EVENT_COMBINATION_SUPPORTED mismatch"
            ));
        }
        Ok(())
    }

